# Probe #2: contact information, and two corrections to probe #1.
#
# READ-ONLY.
#
# Probe #1 found that Spravochnik.Kontragenty has NO address or phone
# attribute at all -- only Kommentariy, which is empty. But it also found
# RegistrSvedeniy.KontaktnayaInformatsiya alive and full: 11109 rows over
# 3341 objects, with real addresses and phone numbers in Predstavlenie.
#
# That matters a lot: the site geocodes clients from Counterparty.address and
# only 375 of 3689 cards have coordinates today, which cripples the client
# map, route building and delivery zones. If those 3341 objects are mostly
# counterparties, the gap closes almost entirely.
#
# So this probe answers what is needed to actually read it:
#   1. What are the register's fields called, and which of them separates an
#      address from a phone number? Tip returned a COM object, so the query
#      has to ask for PREDSTAVLENIE() instead.
#   2. How many DISTINCT counterparties have an address specifically (a phone
#      is useless for geocoding)?
#   3. Probe #1 counted GROUPS, not rows, for the PKO->Sdelka question. It
#      showed the link points at an ORDER rather than a realization, but the
#      volume is still unknown -- and a link present on 5% of payments is not
#      worth building on.
#   4. Incoming goods: 918 posted receipts for 27.2M in a year. Worth reading,
#      but only if the tabular section carries nomenclature and prices.
#
# Run in 32-bit PowerShell:
#   C:\Windows\SysWOW64\WindowsPowerShell\v1.0\powershell.exe -ep bypass -f \\tsclient\Downloads\probe-contacts.ps1 > \\tsclient\Downloads\probe-out2.txt 2>&1

[CmdletBinding()]
param(
    [string] $ConfigPath,
    [int] $Months = 12
)

$ErrorActionPreference = "Stop"

function C([int[]] $codes) { -join ($codes | ForEach-Object { [char]$_ }) }

if (-not $ConfigPath -or -not (Test-Path $ConfigPath)) {
    $candidates = @(
        "C:\Users\fedyshyn\budvik-agent\config.json",
        "C:\Users\fedyshyn\budvik-agent\ps\config.json",
        "C:\budvik-agent\config.json",
        "C:\budvik-agent\ps\config.json"
    )
    $ConfigPath = $null
    foreach ($cand in $candidates) { if (Test-Path $cand) { $ConfigPath = $cand; break } }
    if (-not $ConfigPath) { throw "config.json not found. Pass -ConfigPath <full path>" }
}
Write-Host "using config: $ConfigPath"

$config = [IO.File]::ReadAllText($ConfigPath, [Text.Encoding]::UTF8) | ConvertFrom-Json

$conn = New-Object -ComObject "V82.COMConnector"
$cs = "Srvr=""{0}"";Ref=""{1}"";Usr=""{2}"";Pwd=""{3}"";" -f `
    $config.oneC.server, $config.oneC.base, $config.oneC.user, $config.oneC.password
$ib = $conn.Connect($cs)
Write-Host "CONNECTED to $($config.oneC.base)"
Write-Host ""

$since = (Get-Date).AddMonths(-$Months)

function RunQuery([string] $text) {
    $q = $ib.NewObject("Query")
    $q.Text = $text
    $rs = $q.Execute()
    if ($null -eq $rs) { return $null }
    return $rs.Choose()
}

function Str($v) { if ($null -eq $v) { return "" } else { return [string]$v } }

