# ============================================================
Write-Host "=== 1. CONTACT INFO: which fields exist? ==="
# Field names are discovered by asking for them: referencing a field that is
# not there fails the whole query, which is the only metadata we get over COM.
foreach ($cand in $CI_FIELDS) {
    $text = $CI_FIELD_TPL -replace "@FIELD@", $cand
    try {
        $r = RunQuery $text
        if ($r -and $r.Next()) {
            Write-Host ("  {0}: EXISTS, sample = '{1}'" -f $cand, (Str $r.Get(1)))
        } else {
            Write-Host ("  {0}: EXISTS (no rows)" -f $cand)
        }
    } catch {
        Write-Host ("  {0}: no such field" -f $cand)
    }
}
Write-Host ""

Write-Host "=== 2. CONTACT INFO: kinds, with counts ==="
# PREDSTAVLENIE() turns the enum into text -- reading Tip directly gave a bare
# COM object in probe #1.
try {
    $r = RunQuery $CI_BY_TYPE
    while ($r -and $r.Next()) {
        Write-Host ("  type '{0}': {1} rows, {2} objects" -f (Str $r.Get(0)), $r.Get(1), $r.Get(2))
    }
} catch {
    Write-Host ("  FAILED -- " + $_.Exception.Message)
}
Write-Host ""

Write-Host "=== 3. CONTACT INFO: kinds by Vid (the catalogue) ==="
try {
    $r = RunQuery $CI_BY_VID
    while ($r -and $r.Next()) {
        Write-Host ("  vid '{0}': {1} rows, {2} objects" -f (Str $r.Get(0)), $r.Get(1), $r.Get(2))
    }
} catch {
    Write-Host ("  FAILED -- " + $_.Exception.Message)
}
Write-Host ""

Write-Host "=== 4. How many COUNTERPARTIES have contact info ==="
try {
    $r = RunQuery $CI_CP_COUNT
    if ($r -and $r.Next()) {
        Write-Host ("  counterparties with any contact row: {0}" -f $r.Get(0))
    }
} catch {
    Write-Host ("  FAILED -- " + $_.Exception.Message)
}
Write-Host ""

Write-Host "=== 5. Sample rows for counterparties only ==="
try {
    $r = RunQuery $CI_CP_SAMPLE
    $n = 0
    while ($r -and $r.Next() -and $n -lt 10) {
        Write-Host ("    [{0}] {1} | {2}" -f (Str $r.Get(1)), (Str $r.Get(2)), (Str $r.Get(3)))
        $n++
    }
    if ($n -eq 0) { Write-Host "    (no rows -- Obekt may not be a counterparty reference)" }
} catch {
    Write-Host ("  FAILED -- " + $_.Exception.Message)
}
Write-Host ""

# ============================================================
Write-Host "=== 6. PKO -> Sdelka, counted properly this time ==="
try {
    $q = $ib.NewObject("Query")
    $q.Text = $PKO_SDELKA
    $q.SetParameter($PARAM_FROM, $since)
    $rs = $q.Execute()
    if ($null -eq $rs) { throw "Execute returned null" }
    $r = $rs.Choose()
    $total = 0
    while ($r.Next()) {
        $kind = Str $r.Get(0)
        $cnt = $r.Get(1)
        $sum = $r.Get(2)
        Write-Host ("  {0}: {1} rows, {2}" -f $kind, $cnt, $sum)
        $total += $cnt
    }
    Write-Host ("  total payment rows in {0} months: {1}" -f $Months, $total)
} catch {
    Write-Host ("  FAILED -- " + $_.Exception.Message)
}
Write-Host ""

# ============================================================
Write-Host "=== 7. INCOMING GOODS: does the tabular section carry prices? ==="
try {
    $q = $ib.NewObject("Query")
    $q.Text = $POS_ITEMS
    $q.SetParameter($PARAM_FROM, $since)
    $rs = $q.Execute()
    if ($null -eq $rs) { throw "Execute returned null" }
    $r = $rs.Choose()
    $n = 0
    while ($r.Next() -and $n -lt 5) {
        Write-Host ("    qty={0} price={1} sum={2}" -f $r.Get(1), $r.Get(2), $r.Get(3))
        $n++
    }
    if ($n -eq 0) { Write-Host "    (no rows)" }
} catch {
    Write-Host ("  FAILED -- " + $_.Exception.Message)
}
Write-Host ""

Write-Host "=== 8. Are suppliers marked in the counterparty catalogue? ==="
# The sync reads Pokupatel only, so every counterparty lands as a customer and
# the purchase channel would reject them all as UNMATCHED_SUPPLIER.
foreach ($cand in $SUP_FIELDS) {
    $text = $SUP_TPL -replace "@FIELD@", $cand
    try {
        $r = RunQuery $text
        if ($r -and $r.Next()) {
            Write-Host ("  {0}: EXISTS, {1} of {2} counterparties" -f $cand, $r.Get(0), $r.Get(1))
        }
    } catch {
        Write-Host ("  {0}: no such attribute" -f $cand)
    }
}
Write-Host ""
Write-Host "=== DONE ==="
